node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/travel_expenses.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Travel']);

// Build per-user itineraries with ALL confirmed bookings
const users = {};
data.filter(r => r.Status === 'confirmed').forEach(r => {
  if (!users[r.User]) users[r.User] = [];
  users[r.User].push(r);
});

Object.keys(users).forEach(u => {
  const bookings = users[u];
  const hasHotelOrCar = bookings.some(b => b.Type === 'Hotel' || b.Type === 'Car Rental');
  const flights = bookings.filter(b => b.Type === 'Flight');
  const hotels = bookings.filter(b => b.Type === 'Hotel');
  const cars = bookings.filter(b => b.Type === 'Car Rental');

  console.log('\\n=== ' + u + ' ===');
  console.log('Flights:', flights.map(f => f['Route/Location'] + ' ($' + f.Amount + ')').join(', ') || 'NONE');
  console.log('Hotels:', hotels.map(h => h['Route/Location'] + ' [' + h.Dates + '] ($' + h.Amount + ')').join(', ') || 'NONE');
  console.log('Cars:', cars.map(c => c['Route/Location'].split('→')[0].trim() + ' [' + c.Dates + '] ($' + c.Amount + ')').join(', ') || 'NONE');

  // Identify gaps
  const gaps = [];
  if (hasHotelOrCar && flights.length === 0) gaps.push('NO FLIGHT booked to reach destination');
  if (hotels.length > 0 && cars.length === 0 && !hotels.some(h => h['Route/Location'].includes('Seattle'))) {
    // has hotel but no car - might be fine depending on city
  }
  flights.forEach(f => {
    const route = f['Route/Location'];
    if (route.includes('→')) {
      const [from, to] = route.split('→').map(s => s.trim());
      if (from === to) gaps.push('Round-trip to same airport (' + from + ') - unusual');
    }
  });
  if (gaps.length) console.log('⚠️  GAPS:', gaps.join('; '));
});
"

